  "identity_observations": [
    {"account": "john.smith", "inferred_role": "compromised_account_successful_auth", "first_seen": "2026-02-09T08:17:46+0100"},
    {"account": "alice.jones", "inferred_role": "replayed_breach_credential_attempted", "first_seen": "2026-02-09T08:21:02+0100"},
    {"account": "david.miller", "inferred_role": "replayed_breach_credential_attempted", "first_seen": "2026-02-09T08:24:33+0100"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Reconnaissance / Search Closed Sources — Threat Intel Vendors", "technique": "T1597", "what_happened": "At 2026-02-09 08:14:03 CET, data.srcip=198.51.100.42 — an IP with ZERO prior history in any wazuh-alerts index — issued a single HTTP GET to data.url='/login' on the corporate web/VPN portal 10.108.57.177. No port scan, no host sweep, no directory brute-force preceded this request. The single clean GET captured the login form, CSRF token and session cookie. The DEFINING T1597 signal is precisely this ABSENCE of a recon precursor: the attacker already knew the exact target and the exact valid credentials because they were purchased from a closed source (dark-web access broker / breach-dump vendor), so no noisy enumeration was needed.", "chain_reason": "Suricata / web-proxy logged a lone data.http.method=GET to data.url=/login from data.srcip=198.51.100.42 with NO preceding events from that srcip anywhere in the index. The univariate signal: brand-new external IP + first-ever request is directly against the authentication endpoint, skipping the entire reconnaissance funnel that T1595/T1592 actors must perform.", "first_seen": "2026-02-09T08:14:03+0100"},
    {"step": 2, "tactic": "Initial Access — Valid Accounts", "technique": "T1078", "what_happened": "At 08:17:46 CET — roughly 90 seconds after the portal-discovery GET — data.srcip=198.51.100.42 issued a single HTTP POST to data.url='/login' (data.http.method=POST) carrying data.win.eventdata.targetUserName=john.smith. Windows Security event 4624 (logon success) fired with data.win.eventdata.ipAddress=198.51.100.42 on the FIRST attempt — ZERO preceding 4625 (logon failure) events for that username from that IP. A single precision login that succeeds with no failures is the inverse of brute-force / password-spray: the credential pair was already valid and known. The username john.smith matches the exact persona described in closed-source access-broker listings (corp VPN credential + TOTP MFA secret bundled together).", "chain_reason": "Wazuh rule 5715/5501 (authentication success) with data.win.eventdata.targetUserName=john.smith and data.win.eventdata.ipAddress=198.51.100.42, correlated against the SAME data.srcip from step 1, and crucially with zero rule 5710/5760 (4625 failed logon) events for that pair in the preceding window. First-attempt success from a recon-less external IP = valid-account replay.", "first_seen": "2026-02-09T08:17:46+0100"},
    {"step": 3, "tactic": "Initial Access — Valid Accounts (additional replay)", "technique": "T1078", "what_happened": "Between 08:21:02 and 08:24:33 CET the same data.srcip=198.51.100.42 issued two further HTTP POSTs to data.url='/login' carrying data.win.eventdata.targetUserName=alice.jones then data.win.eventdata.targetUserName=david.miller — each separated by a ~3-minute operator pause (a human checking each result), NOT the sub-second cadence of an automated spray. This is the small targeted set from the breach dump being walked one pair at a time. Each attempt is a single precision shot per user — no password list, no iteration on a single account.", "chain_reason": "Two further authentication events (rule 5715/5710) with data.win.eventdata.targetUserName in {alice.jones, david.miller} and data.win.eventdata.ipAddress=198.51.100.42, with multi-minute inter-attempt gaps. The small, fixed username set + one attempt per user + long human pauses is the closed-source-replay signature, distinct from T1110 spray (many users x many passwords at machine speed).", "first_seen": "2026-02-09T08:21:02+0100"},
    {"step": 4, "tactic": "Discovery / Collection — immediate privileged endpoint access", "technique": "T1078", "what_happened": "Immediately after the john.smith logon success, between 08:25 and 08:30 CET, data.srcip=198.51.100.42 issued a rapid burst of authenticated HTTP GETs to a series of high-value paths: data.url='/admin', '/admin/users', '/api/v1/admin', '/api/v1/users/export', '/finance/dashboard', '/hr/employee-data', '/settings/security', '/api/v1/internal/config'. There was NO exploration phase, NO 404-walking, NO directory brute-force — the attacker went STRAIGHT to known privileged URLs. This is the second T1597 tell: the access-broker listing included the URL map, so the attacker knew exactly where the crown jewels were.", "chain_reason": "A cluster of data.http.method=GET events to data.url matching /admin* and /api/v1/admin* and /api/v1/users/export from data.srcip=198.51.100.42 within a 5-minute window, all carrying the authenticated session established in step 2. Direct privileged-endpoint access with a 0% 404 rate (no enumeration noise) indicates pre-knowledge of the URL structure.", "first_seen": "2026-02-09T08:25:14+0100"},
    {"step": 5, "tactic": "Defense Evasion / Persistence — stolen session token reuse", "technique": "T1078", "what_happened": "Between 08:30 and 08:32 CET, data.srcip=198.51.100.42 sent four HTTP requests to /api/v1/users, /api/v1/admin/settings, /api/v1/internal/keys and /api/v1/reports/financial carrying an Authorization: Bearer token and an X-Auth-Token header — WITHOUT a preceding /login POST for that token. The JWT subject decodes to john.smith with role=admin. Re-using a bearer/session token that was never minted by our own /login flow confirms the access broker also sold a live session artifact alongside the password — the attacker can re-enter even after a password reset.", "chain_reason": "HTTP requests to /api/v1/* carrying an Authorization: Bearer header where the bound principal (john.smith) had no corresponding fresh 4624/login event in the immediate window — token presented out-of-band. Token reuse without authentication is the persistence tail of a closed-source credential+session purchase.", "first_seen": "2026-02-09T08:30:48+0100"}
  ],
